class Solution {
    public long sumDigitDifferences(int[] nums) {
        int n = nums.length;
        int m = String.valueOf(nums[0]).length();
        long ans = 0;
        for (int step = 0; step < m; ++step) {
            int[] cnt = new int[10];
            for (int i = 0; i < n; ++i) {
                cnt[nums[i] % 10]++;
                nums[i] /= 10;
            }
            for (int d = 0; d < 10; ++d) {
                ans += (long) cnt[d] * (n - cnt[d]);
            }
        }
        return ans / 2;
    }
}

var sumDigitDifferences = function(nums) {
    const n = nums.length;
    const m = String(nums[0]).length;
    let ans = 0;
    for (let step = 0; step < m; ++step) {
        const cnt = new Array(10).fill(0);
        for (let i = 0; i < n; ++i) {
            cnt[nums[i] % 10]++;
            nums[i] = Math.floor(nums[i] / 10);
        }
        for (let d = 0; d < 10; ++d) {
            ans += cnt[d] * (n - cnt[d]);
        }
    }
    return Math.floor(ans / 2);
};
